import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { kind1Schema, type Kind1 } from "./kind1.js";
import { segmentLineSchema, type SegmentLine } from "./segment-line.js";
import {
  segmentTranslationMetadataSchema,
  type SegmentTranslationMetadata,
} from "./segment-translation-metadata.js";
import { segmentWordsSchema, type SegmentWords } from "./segment-words.js";

export type Segment = {
  /** Whether the segment is autogenerated. */
  autogenerated: boolean;
  /** The cue end timestamp in milliseconds from the start of the video. */
  cueEnd: number;
  /** The cue start timestamp in milliseconds from the start of the video. */
  cueStart: number;
  /** Whether the segment is enabled. */
  enabled: boolean;
  /** The segment identifier. */
  id: string;
  /**
   * The type of caption that the segment originates from.
   *
   * Option descriptions:
   *  * `captions` - The segment originates from a captions file.
   *  * `subtitles` - The segment originates from a captions and subtitles file.
   */
  kind: Kind1;
  /** The language of the segment. */
  language: string;
  /** The line data for the segment. */
  lines: SegmentLine[];
  /** The speaker identifier. */
  speaker: string | null;
  /** The relative URI of the text track that the segment comes from. */
  textTrackUri: string;
  /** The translation metadata of the segment. */
  translationMetadata?: SegmentTranslationMetadata;
  /** The canonical relative URI of the segment's video. */
  videoUri?: string;
  /** The word data for the segment. */
  words: SegmentWords[];
};

export const segmentSchema: Schema<Segment> = s.object<Segment>({
  autogenerated: s.boolean(),
  cueEnd: s.float64(),
  cueStart: s.float64(),
  enabled: s.boolean(),
  id: s.string(),
  kind: kind1Schema,
  language: s.string(),
  lines: s.array(s.lazy(() => segmentLineSchema)),
  speaker: s.nullable(s.string()),
  textTrackUri: s.string(),
  translationMetadata: s.optional(s.lazy(() => segmentTranslationMetadataSchema)),
  videoUri: s.optional(s.string()),
  words: s.array(s.lazy(() => segmentWordsSchema)),
  _keysMap: {
    cueEnd: "cue_end",
    cueStart: "cue_start",
    textTrackUri: "text_track_uri",
    translationMetadata: "translation_metadata",
    videoUri: "video_uri",
  },
});
